{
  "gate_token": "ZToxzj9WYnsjs7KLv364OQ",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined city at dawn.",
      "visual_description": "A windswept hilltop overlooking a shattered skyline of broken spires; an ink-stained coat flaps as a brass compass spins.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Oracle Lamp warns of temptations ahead.",
      "visual_description": "A battered oil lamp held aloft, its single flame-eye blazing as it casts long warning shadows across cracked cobblestones.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The Tin Fox scouts the broken castle gates.",
      "visual_description": "A small clockwork fox with blue glass eyes peers between iron bars of a half-collapsed gate, key-wind tail ticking softly.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The Glass Diver emerges from a rain puddle reflection.",
      "visual_description": "A figure in a clear diving helmet rises out of a shallow puddle, coat shimmering with refracted city lights.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "They find the Sleeping Tax Collector dozing at the checkpoint.",
      "visual_description": "A snoring official slumped over a ledger pillow, stamped papers stuck to his sleeves, beneath a tattered royal banner.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The Oracle Lamp identifies a cursed tower on the map.",
      "visual_description": "Lamplight flickers across a parchment map; a finger-shaped shadow points to a leaning tower wreathed in green smoke.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "The Tin Fox darts past an armored patrol unnoticed.",
      "visual_description": "Tiny brass paws skitter through a sewer grate while heavy boots and pike-shadows pass overhead in moonlight.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "Rumors of a winged beast echo from the rooftops.",
      "visual_description": "Mara crouches behind a chimney as a vast shadow sweeps across torn banners; the Lamp's eye narrows in alarm.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The Glass Diver slips through a stained-glass window.",
      "visual_description": "A coat ripples like water as the diver passes bodily through a colored window, leaving glass intact but glowing.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Inside the tower, the team finds the magic door.",
      "visual_description": "A tall arched door pulsing with runes that shift like fish under ice; the Tin Fox sniffs its lower hinge.",
      "characters": ["glass_diver", "tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "The Oracle Lamp speaks the door's true name.",
      "visual_description": "The lamp's flame-eye stretches wide; runes on the door bend toward the light and unspool into a keyhole.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "They discover the Sleeping Tax Collector chained inside.",
      "visual_description": "The official dozes in an iron chair, ledger-pillow still tucked under his chin, rusty chains looped through stamped pages.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The Tin Fox picks the lock with its key-tail.",
      "visual_description": "The fox twists its wind-key into a chain shackle; sparks ping off cold stone as the cuff falls open.",
      "characters": ["tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 14,
      "caption": "Alarm bells ring; the patrol closes in.",
      "visual_description": "Red torchlight floods a spiral stairwell; Mara waves the team upward while the Lamp dims to a whisper.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "The Glass Diver pulls them through a mirrored hall.",
      "visual_description": "Hands clasp in a chain as the diver wades into a tall mirror, the surface rippling outward like dropped silver.",
      "characters": ["glass_diver", "mara_the_cartographer", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "They emerge near the river bridge at moonrise.",
      "visual_description": "A long stone bridge arches over black water; broken royal banners flap from its lampposts as the team regroups.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The Oracle Lamp lights the path across the bridge.",
      "visual_description": "A single warm beam stretches the length of the span; the Tin Fox trots ahead, tail ticking in steady rhythm.",
      "characters": ["oracle_lamp", "tin_fox", "mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far shore, Mara marks the map complete.",
      "visual_description": "Dawn breaks behind the ruined skyline; an ink-stained hand stamps a small star on the map while the diver's helmet catches first light.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

